import { test, expect } from '@playwright/test';

test.describe('Modal with Video - Pause on Close', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to the page containing the modal with video
    await page.goto('http://localhost:3000');
  });

  test('should pause video when modal is closed via close button', async ({ page }) => {
    // Open the modal by clicking the button
    const openModalButton = page.getByRole('button', { name: /open modal/i });
    await openModalButton.click();

    // Verify modal is visible
    const modal = page.getByRole('dialog');
    await expect(modal).toBeVisible();

    // Get the video element
    const video = page.locator('video');
    await expect(video).toBeVisible();

    // Play the video
    await video.evaluate((el: HTMLVideoElement) => el.play());

    // Wait a moment for video to start playing
    await page.waitForTimeout(500);

    // Verify video is playing
    const isPlaying = await video.evaluate((el: HTMLVideoElement) => !el.paused);
    expect(isPlaying).toBe(true);

    // Close the modal by clicking the close button
    const closeButton = page.getByRole('button', { name: /close|×/i }).first();
    await closeButton.click();

    // Verify modal is closed
    await expect(modal).not.toBeVisible();

    // Verify video is paused
    const isPaused = await video.evaluate((el: HTMLVideoElement) => el.paused);
    expect(isPaused).toBe(true);
  });

  test('should pause video when modal is closed via backdrop click', async ({ page }) => {
    // Open the modal
    const openModalButton = page.getByRole('button', { name: /open modal/i });
    await openModalButton.click();

    // Verify modal is visible
    const modal = page.getByRole('dialog');
    await expect(modal).toBeVisible();

    // Get the video element
    const video = page.locator('video');
    await expect(video).toBeVisible();

    // Play the video
    await video.evaluate((el: HTMLVideoElement) => el.play());

    // Wait for video to start playing
    await page.waitForTimeout(500);

    // Verify video is playing
    const isPlayingBefore = await video.evaluate((el: HTMLVideoElement) => !el.paused);
    expect(isPlayingBefore).toBe(true);

    // Click on the backdrop to close modal
    const backdrop = page.locator('[class*="backdrop"], [class*="overlay"]').first();
    if (await backdrop.isVisible()) {
      await backdrop.click();
    }

    // Verify modal is closed
    await expect(modal).not.toBeVisible();

    // Verify video is paused
    const isPausedAfter = await video.evaluate((el: HTMLVideoElement) => el.paused);
    expect(isPausedAfter).toBe(true);
  });

  test('should maintain video pause state after reopening modal', async ({ page }) => {
    // Open the modal
    const openModalButton = page.getByRole('button', { name: /open modal/i });
    await openModalButton.click();

    // Verify modal is visible
    const modal = page.getByRole('dialog');
    await expect(modal).toBeVisible();

    // Get the video element
    const video = page.locator('video');
    await expect(video).toBeVisible();

    // Play the video
    await video.evaluate((el: HTMLVideoElement) => el.play());

    // Wait for video to start playing
    await page.waitForTimeout(500);

    // Close the modal
    const closeButton = page.getByRole('button', { name: /close|×/i }).first();
    await closeButton.click();

    // Verify modal is closed and video is paused
    await expect(modal).not.toBeVisible();
    let isPaused = await video.evaluate((el: HTMLVideoElement) => el.paused);
    expect(isPaused).toBe(true);

    // Reopen the modal
    await openModalButton.click();
    await expect(modal).toBeVisible();

    // Verify video is still paused
    isPaused = await video.evaluate((el: HTMLVideoElement) => el.paused);
    expect(isPaused).toBe(true);
  });

  test('should pause video and preserve current time when modal is closed', async ({ page }) => {
    // Open the modal
    const openModalButton = page.getByRole('button', { name: /open modal/i });
    await openModalButton.click();

    // Verify modal is visible
    const modal = page.getByRole('dialog');
    await expect(modal).toBeVisible();

    // Get the video element
    const video = page.locator('video');
    await expect(video).toBeVisible();

    // Play the video
    await video.evaluate((el: HTMLVideoElement) => el.play());

    // Wait for video to progress
    await page.waitForTimeout(1000);

    // Get the current time
    const currentTimeBefore = await video.evaluate((el: HTMLVideoElement) => el.currentTime);
    expect(currentTimeBefore).toBeGreaterThan(0);

    // Close the modal
    const closeButton = page.getByRole('button', { name: /close|×/i }).first();
    await closeButton.click();

    // Verify modal is closed
    await expect(modal).not.toBeVisible();

    // Verify video is paused
    const isPaused = await video.evaluate((el: HTMLVideoElement) => el.paused);
    expect(isPaused).toBe(true);

    // Verify current time is preserved
    const currentTimeAfter = await video.evaluate((el: HTMLVideoElement) => el.currentTime);
    expect(currentTimeAfter).toBe(currentTimeBefore);
  });
});
